import itertools,random,importlib.util,json,subprocess,sys
spec=importlib.util.spec_from_file_location('s','/workspace/submission/main.py');s=importlib.util.module_from_spec(spec);spec.loader.exec_module(s)
verts=[1,2,3,4,5]
cp={}
# all permutations length 5, counts1
for p in itertools.permutations(verts):
 cp[p]=1
rounds,cur,core=s.peel(cp)
print('rounds',len(rounds),'core',len(core),'cur paths',len(cur))
edges=sorted(core);ei={e:i for i,e in enumerate(edges)}
sc,occ=s.build_scopes_and_occurrences(cur,ei)
print('m',len(edges),'scopes',[len(x) for x in sc])
# greedy find order width<=4
m=len(edges);adj=[set() for _ in range(m)]
for scope in sc:
 x=list(scope)
 for i in range(len(x)):
  for j in range(i+1,len(x)):
   adj[x[i]].add(x[j]);adj[x[j]].add(x[i])
left=set(range(m));order=[]
while left:
 x=min(left,key=lambda v:(len(adj[v]),v));left.remove(x);order.append(x)
 if len(adj[x])>4:
  print('bad greedy deg',len(adj[x]));break
 ne=list(adj[x])
 for i in range(len(ne)):
  for j in range(i+1,len(ne)):
   adj[ne[i]].add(ne[j]);adj[ne[j]].add(ne[i])
 for y in ne:adj[y].discard(x)
 adj[x].clear()
else:
 print('found order',order,'degs ok')
 # order mapping edges list in order
 order_links=[list(edges[x]) for x in order]
 data={'version':1,'ixps':[],'rib':[{'path':list(p),'count':1} for p in cp],'priors':[],'declared':[],'order':order_links,'queries':[]}
 r=subprocess.run([sys.executable,'-I','/workspace/submission/main.py'],input=json.dumps(data).encode(),stdout=subprocess.PIPE)
 print('out bytes',len(r.stdout),r.stdout[:200])
PY
